#!/usr/bin/env python3
"""BYG SELEN (13/9). Selen er appen med en falsk Supabase (svarer 'tom base' paa alt, giver en falsk session).
Den maa ALDRIG ligge som filer i repoet: en index-sele.html paa det levende site ville vaere appen med en
falsk bruger. Derfor bygges den HER, i en mappe uden for repoet, hver gang maalingen koerer:

    python3 tools/designlaas/byg-sele.py <maalmappe>

Mappen faar sele.html, sb-stub.js og index-sele.html (index.html med Supabase-scriptet byttet til stubben)
plus symlinks/kopier af de filer, appen loader (billeder, sw.js, manifest). Server mappen paa port 4600 og koer
tools/designlaas/koer.sh. Samme sele som bilaget i docs/superpowers/plans/2026-09-12-status-backstage-2027.md."""
import os, shutil, sys
STUB = '/* SELE-STUB: erstatter Supabase i selen. Svarer "tom base" paa alt, og giver en falsk session. Maa ALDRIG deployes. */\n(function () {\n  var KODE = (new URLSearchParams(location.search).get("selekode") || window.__SELE_KODE || "RINGKOBING2026").toUpperCase();\n  var user = { id: "sele-test", email: "sele@test.dk", app_metadata: { kode: KODE }, user_metadata: { navn: "Test", hilsen: "Test", kode: KODE } };\n  var session = { user: user, access_token: "sele", refresh_token: "sele", expires_at: 9999999999 };\n  var LAT = parseInt(new URLSearchParams(location.search).get("selelat") || (window.parent && window.parent !== window ? (new URLSearchParams(window.parent.location.search).get("selelat") || "0") : "0"), 10) || 0;\n  function svar(v) { if (!LAT) return Promise.resolve(v); window.__NET = (window.__NET || 0) + 1; return new Promise(function (r) { setTimeout(function () { window.__NET = Math.max(0, (window.__NET || 0) - 1); r(v); try { if (window.__NET_RO) window.__NET_RO(); } catch (e) {} }, LAT); }); }\n  function builder() {\n    var st = { single: false, rows: [] };\n    var p = new Proxy(function () {}, {\n      get: function (_, navn) {\n        if (navn === "then") { var r = { data: st.single ? null : st.rows, error: null, count: st.rows.length, status: 200 }; return function (res, rej) { return svar(r).then(res, rej); }; }\n        if (navn === "catch" || navn === "finally") { return function (fn) { return svar({ data: st.single ? null : st.rows, error: null }); }; }\n        return function () {\n          var a = arguments[0];\n          if (navn === "single" || navn === "maybeSingle") st.single = true;\n          if (navn === "insert" || navn === "upsert") st.rows = Array.isArray(a) ? a.map(function (r, i) { return Object.assign({ id: "sele-" + Date.now() + "-" + i }, r); }) : [Object.assign({ id: "sele-" + Date.now() }, a || {})];\n          if (navn === "update") st.rows = [Object.assign({ id: "sele-upd" }, a || {})];\n          return p;\n        };\n      }\n    });\n    return p;\n  }\n  var sb = {\n    from: function (t) { try { (window.__NET_LOG = window.__NET_LOG || []).push(Math.round(performance.now()) + " from " + t); } catch (e) {} return builder(); },\n    rpc: function (t) { try { (window.__NET_LOG = window.__NET_LOG || []).push(Math.round(performance.now()) + " rpc " + t); } catch (e) {} return builder(); },\n    auth: {\n      getUser: function () { return svar({ data: { user: user }, error: null }); },\n      getSession: function () { return svar({ data: { session: session }, error: null }); },\n      onAuthStateChange: function (cb) { setTimeout(function () { try { cb("SIGNED_IN", session); } catch (e) {} }, 0); return { data: { subscription: { unsubscribe: function () {} } } }; },\n      signInWithPassword: function () { return svar({ data: { user: user, session: session }, error: null }); },\n      signOut: function () { return svar({ error: null }); },\n      updateUser: function () { return svar({ data: { user: user }, error: null }); },\n      setSession: function () { return svar({ data: { session: session, user: user }, error: null }); },\n      refreshSession: function () { return svar({ data: { session: session, user: user }, error: null }); },\n      resetPasswordForEmail: function () { return svar({ data: {}, error: null }); },\n      signUp: function () { return svar({ data: { user: user, session: session }, error: null }); }\n    },\n    channel: function () { var c = { on: function () { return c; }, subscribe: function () { return c; }, unsubscribe: function () {} }; return c; },\n    removeChannel: function () {},\n    storage: { from: function () { return { getPublicUrl: function () { return { data: { publicUrl: "" } }; }, upload: function () { return svar({ data: null, error: null }); }, list: function () { return svar({ data: [], error: null }); }, remove: function () { return svar({ data: [], error: null }); } }; } },\n    functions: { invoke: function () { return svar({ data: null, error: null }); } }\n  };\n  window.supabase = { createClient: function () { return sb; } };\n  window.__SELE_SB = sb;\n})();\n'
SELE = '<!doctype html><meta charset="utf-8"><title>sele</title><body style="margin:0">\n<script>\nconst P = k => new URLSearchParams(location.search).get(k);\nconst side = P(\'side\') || \'overblik\', bred = parseInt(P(\'bred\') || \'390\', 10), hoej = parseInt(P(\'hoej\') || \'1200\', 10);\nconst f = document.createElement(\'iframe\'); f.style.cssText = \'border:0;width:\' + bred + \'px;height:\' + hoej + \'px;display:block\'; f.src = (P(\'fil\') || \'index.html\') + (P(\'hash\') ? decodeURIComponent(P(\'hash\')) : (P(\'vis\') === \'kunde\' ? \'\' : \'#admin\')); document.body.appendChild(f);\nlet n = 0;\nfunction tick() {\n  n++; const w = f.contentWindow; let ok = false; try { ok = (P(\'vis\') === \'kunde\' ? typeof w.showTab === \'function\' : typeof w.visDashSide === \'function\') && w.document.readyState === \'complete\'; } catch (e) {}\n  if (!ok) { if (n < 250) return setTimeout(tick, 80); console.log(\'SELE: visDashSide aldrig klar\'); return; }\n  if (P(\'vis\') === \'kunde\') { setTimeout(() => { try { if (P(\'tab\') !== null && typeof w.showTab === \'function\') w.showTab(parseInt(P(\'tab\'), 10)); } catch (e) { console.log(\'SELE tab: \' + e.message); } if (P(\'kode\')) { try { w.eval(P(\'kode\')); } catch (e) { console.log(\'SELE kode: \' + e.message); } } }, 1200); setTimeout(maal, 3500); return; }\n  try {\n    const d = w.document; try { if (typeof w.authSkip === \'function\') w.authSkip(); } catch (e) { console.log(\'SELE authSkip: \' + e.message); }\n    const g = d.getElementById(\'authGate\'); if (g) g.remove();\n    d.body.classList.add(\'dash-mode\');\n    [\'dashMain\', \'dashboard\'].forEach(id => { const e = d.getElementById(id); if (e) e.style.display = \'block\'; });\n    [\'dashLogin\', \'app\'].forEach(id => { const e = d.getElementById(id); if (e) e.style.display = \'none\'; });\n    w.visDashSide(side);\n    setTimeout(() => { try { if (typeof w.studieVaelgerLuk === \'function\') w.studieVaelgerLuk(); } catch (e) {} }, 300);\n    const l = d.getElementById(\'appLoader\'); if (l) l.remove();\n    if (P(\'kode\')) setTimeout(() => { try { w.eval(P(\'kode\')); } catch (e) { console.log(\'SELE kode: \' + e.message); } }, 600);\n  } catch (e) { console.log(\'SELE fejl: \' + e.message); }\n  setTimeout(maal, 2500);\n}\nfunction maal() {\n  try {\n    const d = f.contentDocument, w = f.contentWindow; const sw = d.documentElement.scrollWidth, iw = w.innerWidth;\n    const rod = d.getElementById(P(\'vis\') === \'kunde\' ? \'app\' : \'dashMain\') || d.body;\n    console.log(\'SELE MAAL side=\' + side + \' bred=\' + iw + \' scrollWidth=\' + sw + \' overloeb=\' + (sw > iw ? \'JA\' : \'nej\') + \' tekst=\' + (rod.innerText || \'\').replace(/\\s+/g, \' \').slice(0, 260));\n  } catch (e) { console.log(\'SELE maal fejl: \' + e.message); }\n}\ntick();\n</script>\n'
def byg(rod, maal):
    os.makedirs(maal, exist_ok=True)
    s = open(os.path.join(rod, "index.html"), encoding="utf-8").read()
    tag = '<script src="https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2"></script>'
    if tag not in s: raise SystemExit("Supabase-scriptet blev ikke fundet i index.html — selen kan ikke bygges")
    # INGEN SERVICE WORKER I SELEN (MAALT 15/9): appens sw.js cachede index-sele.html paa port 4633, saa hver
    # ny bygning blev maalt paa en GAMMEL kopi, indtil SW'en blev afregistreret med haanden. Selen maa aldrig cache.
    ude = s.replace(tag, '<script src="sb-stub.js"></script>', 1).replace('navigator.serviceWorker.register("sw.js").catch(function(){});', '/* SELE: ingen service worker */ try { navigator.serviceWorker.getRegistrations().then(function (rs) { rs.forEach(function (r) { r.unregister(); }); }); } catch (e) {}', 1)
    open(os.path.join(maal, "index-sele.html"), "w", encoding="utf-8").write(ude)
    open(os.path.join(maal, "sb-stub.js"), "w", encoding="utf-8").write(STUB)
    open(os.path.join(maal, "sele.html"), "w", encoding="utf-8").write(SELE)
    for navn in os.listdir(rod):
        if navn.startswith(".") or navn in ("index.html", "tools", "docs"): continue
        kilde = os.path.join(rod, navn); dest = os.path.join(maal, navn)
        if os.path.exists(dest): continue
        if os.path.isdir(kilde): shutil.copytree(kilde, dest)
        else: shutil.copy2(kilde, dest)
    print("sele bygget i " + maal)
if __name__ == "__main__":
    rod = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
    byg(rod, sys.argv[1] if len(sys.argv) > 1 else os.path.join(os.path.dirname(rod), "sele-run"))
